const note=document.querySelector('#login-note'),localButton=document.querySelector('#local-login');
fetch('/api/local-mode').then(r=>r.ok?r.json():null).then(data=>{if(!data?.local)return;document.querySelector('#cloud-login').hidden=true;localButton.hidden=false;note.textContent='Локальна панель доступна лише на цьому ноутбуці. Зміни зберігаються тут і не впливають на опублікований сайт.';}).catch(()=>{});
localButton.addEventListener('click',async()=>{localButton.disabled=true;try{const result=await fetch('/api/local-session',{method:'POST',headers:{'X-Admin-Request':'1'}});if(!result.ok)throw new Error('Не вдалося увійти. Відкрийте цю сторінку на ноутбуці, де запущено попередній перегляд.');location.href='/admin/';}catch(e){note.textContent='Не вдалося увійти. Перевірте з’єднання та відкрийте панель на ноутбуці, де запущено попередній перегляд.';localButton.disabled=false;}});
